// Extrai e combina notícias dos RSS
const g1Items = items[0]?.json?.items || [];
const bbcItems = items[1]?.json?.items || [];

// Combina e embaralha
const todasNoticias = [...g1Items, ...bbcItems]
  .filter(item => item?.title && item?.description)
  .sort(() => Math.random() - 0.5)
  .slice(0, 5); // Pega 5 notícias aleatórias

return todasNoticias.map(noticia => ({
  json: {
    titulo: noticia.title.replace(/\s+/g, ' ').trim(),
    descricao: noticia.description?.replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim() || '',
    link: noticia.link || '',
    dataPublicacao: noticia.pubDate || new Date().toISOString()
  }
}));

// Gera roteiro de humor baseado em templates
const noticia = $input.item.json;

// Templates de humor (estilo stand-up/sátira)
const templates = [
  {
    nome: "Ironia da Realidade",
    roteiro: `🎭 VOCÊ NÃO VAI ACREDITAR! \n\n${noticia.titulo}\n\nÉ... meus amigos, a realidade superou a ficção de novo! Enquanto isso nos comentários: "mas que país é esse?" 😂\n\n#humor #satira #noticias #brasil`
  },
  {
    nome: "Pergunta Retórica",
    roteiro: `🤔 SÉRIO ISSO MESMO? \n\n${noticia.titulo}\n\nAlguém aí também ficou sem palavras ou só eu? Deixa nos comentários qual sua reação! 👇\n\n#humor #comentario #atualidades #viral`
  },
  {
    nome: "Comparação Engraçada",
    roteiro: `😂 ISSO AÍ É TIPO... \n\n${noticia.titulo}\n\nÉ igual tentar explicar pra sua avó o que é Bitcoin. Ninguém entende, mas todo mundo opina! 🤷\n\n#humor #comparacao #noticiasdodia #meme`
  },
  {
    nome: "Plot Twist",
    roteiro: `🎬 PLOT TWIST DO ANO! \n\n${noticia.titulo}\n\nE eu que achei que minha vida era dramática... A realidade sempre vence! Marca aquele amigo que precisa ver isso 👇\n\n#plottwist #humor #realidade #tiktokbrasil`
  },
  {
    nome: "Reação Exagerada",
    roteiro: `🚨 ALERTA DE NOTÍCIA BIZARRA! \n\n${noticia.titulo}\n\nMINHA REAÇÃO: 😱🤯😵\n\nQuem mais tá assim? Comenta aí! \n\n#reacao #humor #noticiabizarra #viralizou`
  }
];

// Seleciona template aleatório
const template = templates[Math.floor(Math.random() * templates.length)];

return {
  json: {
    ...noticia,
    roteiro: template.roteiro,
    templateUsado: template.nome,
    hashtags: template.roteiro.match(/#[\wçãõáéíóú\-]+/g)?.join(' ') || '#humor #noticias',
    duracaoEstimada: '15-30 segundos'
  }
};

// Formata saída para exibição
const dados = $input.item.json;

return {
  json: {
    mensagem: "✅ Roteiro gerado com sucesso!",
    noticia_original: dados.titulo,
    template_usado: dados.templateUsado,
    roteiro_completo: dados.roteiro,
    hashtags: dados.hashtags,
    arquivo_salvo: dados.caminhoVideo.replace('.mp4', '_roteiro.txt'),
    proximo_passo: "Grave o vídeo usando este roteiro e faça upload manual ou configure a API do TikTok"
  }
};
